package at.foama.wien;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Looper;import android.view.*;import android.widget.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w227dp-h227dp-round-xhdpi") @LooperMode(LooperMode.Mode.PAUSED)
public class JourneyImportTest {
 @Before public void clean(){RuntimeEnvironment.getApplication().getSharedPreferences("foama",0).edit().clear().commit();}
 private JSONObject value()throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get("tests/fixtures/transfer-routes-webcrypto.json")),StandardCharsets.UTF_8)).getJSONObject("value");}
 private TextView find(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView t=find(((ViewGroup)v).getChildAt(i),label);if(t!=null)return t;}return null;}
 private void click(MainActivity app,String label){View v=find(app.getWindow().getDecorView(),label);assertNotNull(label,v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();assertTrue(v.performClick());}
 private void completeIo(MainActivity app,String field)throws Exception{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(field);f.setAccessible(true);((Future<?>)f.get(app)).get(5,TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void routesAreDiscoverableWithNoFavoritesAndBothImportChoicesAreAvailable(){
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{click(app,"A nach B");assertEquals("routes",app.screen);assertNotNull(find(app.getWindow().getDecorView(),"Deine gespeicherten Fahrten"));assertNotNull(find(app.getWindow().getDecorView(),"Aus PWA übernehmen"));click(app,"Datei importieren");Intent intent=org.robolectric.Shadows.shadowOf(app).getNextStartedActivityForResult().intent;assertEquals(Intent.ACTION_OPEN_DOCUMENT,intent.getAction());assertEquals("application/json",intent.getType());assertTrue(intent.hasCategory(Intent.CATEGORY_OPENABLE));assertTrue(app.repo.journeys.all().length()==0);app.navigateBack();assertEquals("routes",app.screen);app.navigateBack();assertEquals("home",app.screen);assertFalse(app.isFinishing());}finally{c.stop().destroy();}
 }
 @Test public void importedRoutesArePreviewedBeforeSavingAndRemainAvailableWithCurrentTimesAfterRestart()throws Exception{
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{
   app.repo.nextFetchElapsed=Long.MAX_VALUE;app.openRoutes();c.resume();app.chooseFavoriteFile();Uri uri=Uri.parse("content://files/foama-favorites.json");org.robolectric.Shadows.shadowOf(app.getContentResolver()).registerInputStream(uri,new ByteArrayInputStream(value().toString().getBytes(StandardCharsets.UTF_8)));
   app.onActivityResult(MainActivity.IMPORT_FILE,Activity.RESULT_OK,new Intent().setData(uri));completeIo(app,"fileRequest");assertEquals(0,app.repo.journeys.all().length());assertEquals(0,app.repo.favorites.size());assertTrue((app.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);click(app,"Favoriten übernehmen");assertEquals("routes",app.screen);assertEquals(1,app.repo.journeys.all().length());assertTrue((app.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)==0);
   JSONObject route=app.repo.journeys.all().getJSONObject(0);app.openJourney(route.getString("id"));app.navigateBack();assertEquals("routes",app.screen);assertFalse(app.isFinishing());assertEquals(1,new Repo(app).journeys.all().length());c.pause();
  }finally{c.stop().destroy();}
 }
 @Test public void boundedFileReaderClosesStreamsAndRejectsMalformedOrOversizedFilesBeforeAnyMutation()throws Exception{
  Repo repo=new Repo(RuntimeEnvironment.getApplication());AtomicInteger closed=new AtomicInteger();InputStream good=new ByteArrayInputStream(value().toString().getBytes(StandardCharsets.UTF_8)){public void close(){closed.incrementAndGet();}};
  assertEquals(1,FavoriteFile.preview(good,repo,new RequestScope()).journeys.length());assertEquals(1,closed.get());assertEquals(0,repo.journeys.all().length());
  for(byte[] bytes:new byte[][]{new byte[FavoriteFile.MAX_BYTES+1],"{bad json".getBytes(StandardCharsets.UTF_8),new byte[]{(byte)0xc3,0x28}}){try{FavoriteFile.preview(new ByteArrayInputStream(bytes),repo,new RequestScope());fail("Invalid file accepted");}catch(Exception expected){}assertEquals(0,repo.journeys.all().length());assertTrue(repo.favorites.isEmpty());}
  RequestScope cancelled=new RequestScope();cancelled.cancel();try{FavoriteFile.preview(new ByteArrayInputStream(value().toString().getBytes(StandardCharsets.UTF_8)),repo,cancelled);fail();}catch(InterruptedIOException expected){}assertTrue(repo.favorites.isEmpty());
 }
 @Test public void leavingFilePreviewCannotImportItLater()throws Exception{
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{app.repo.nextFetchElapsed=Long.MAX_VALUE;app.openRoutes();c.resume();app.chooseFavoriteFile();Uri uri=Uri.parse("content://files/foama.json");org.robolectric.Shadows.shadowOf(app.getContentResolver()).registerInputStream(uri,new ByteArrayInputStream(value().toString().getBytes(StandardCharsets.UTF_8)));app.onActivityResult(MainActivity.IMPORT_FILE,Activity.RESULT_OK,new Intent().setData(uri));completeIo(app,"fileRequest");c.pause();app.confirmFileImport();assertEquals(0,app.repo.journeys.all().length());assertTrue((app.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)==0);}finally{c.stop().destroy();}
 }
 @Test public void settingsFileImportPreviewsBothFavoriteTypesAndReturnsToTheImportMenu()throws Exception{
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{
   app.repo.nextFetchElapsed=Long.MAX_VALUE;app.repo.toggleFavorite(app.repo.stops.get(0),"KEEP","Kept");c.resume();click(app,"Mehr");click(app,"Favoriten");click(app,"Aus PWA importieren");assertNotNull(find(app.getWindow().getDecorView(),"Alle Favoriten"));assertNotNull(find(app.getWindow().getDecorView(),"Per QR übernehmen"));click(app,"Datei importieren");app.navigateBack();assertNotNull(find(app.getWindow().getDecorView(),"Alle Favoriten"));click(app,"Datei importieren");
   Uri uri=Uri.parse("content://files/foama-favorites.json");org.robolectric.Shadows.shadowOf(app.getContentResolver()).registerInputStream(uri,new ByteArrayInputStream(value().toString().getBytes(StandardCharsets.UTF_8)));app.onActivityResult(MainActivity.IMPORT_FILE,Activity.RESULT_OK,new Intent().setData(uri));completeIo(app,"fileRequest");
   assertNotNull(find(app.getWindow().getDecorView(),"Haltestellen & Linien"));assertNotNull(find(app.getWindow().getDecorView(),"A nach B"));assertEquals(1,app.repo.favorites.size());assertEquals(0,app.repo.journeys.all().length());click(app,"Favoriten übernehmen");assertEquals("more",app.screen);assertNotNull(find(app.getWindow().getDecorView(),"Alle Favoriten"));assertNotNull(find(app.getWindow().getDecorView(),"1 Station/Linie und 1 Route übernommen."));assertEquals(2,app.repo.favorites.size());assertEquals("KEEP",app.repo.favorites.get(0).route);assertEquals(1,app.repo.journeys.all().length());
   Repo restarted=new Repo(app);assertEquals(2,restarted.favorites.size());assertEquals(1,restarted.journeys.all().length());app.navigateBack();assertNotNull(find(app.getWindow().getDecorView(),"Aus PWA importieren"));assertFalse(app.isFinishing());c.pause();
  }finally{c.stop().destroy();}
 }
 @Test public void settingsQrImportOpensConfirmedFavoritesAndCancellationStillKeepsItsParent()throws Exception{
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{
   app.repo.nextFetchElapsed=Long.MAX_VALUE;app.repo.toggleFavorite(app.repo.stops.get(0),"KEEP","Kept");c.resume();app.transferConnectionFactory=url->new Fake(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"waiting\"}");click(app,"Mehr");click(app,"Favoriten");click(app,"Aus PWA importieren");click(app,"Per QR übernehmen");completeIo(app,"transferRequest");assertEquals("transfer",app.screen);assertEquals("to-watch",app.transfer.direction);
   app.transferPreview=TransferManager.preview(value(),app.repo);app.renderContent();assertEquals(1,app.repo.favorites.size());assertEquals(0,app.repo.journeys.all().length());click(app,"Favoriten übernehmen");completeIo(app,"transferRequest");assertEquals(2,app.repo.favorites.size());assertEquals(1,app.repo.journeys.all().length());assertEquals("home",app.screen);assertEquals("fav",app.view);assertEquals("routes",app.repo.prefs.getString("favoriteView",""));assertNotNull(find(app.getWindow().getDecorView(),"Meine Routen"));click(app,"Mehr");click(app,"Favoriten");click(app,"Aus PWA importieren");assertNotNull(find(app.getWindow().getDecorView(),"Alle Favoriten"));click(app,"Per QR übernehmen");completeIo(app,"transferRequest");c.pause();assertNull(app.transfer);assertEquals("more",app.screen);java.lang.reflect.Field section=MainActivity.class.getDeclaredField("settingsSection");section.setAccessible(true);assertEquals("import",section.get(app));assertFalse((app.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);
  }finally{c.stop().destroy();}
 }
 private static class Fake extends HttpURLConnection {final String body;Fake(URL url,String body){super(url);this.body=body;}public int getResponseCode(){return 200;}public InputStream getInputStream(){return new ByteArrayInputStream(body.getBytes(StandardCharsets.UTF_8));}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}}
 @Test public void activityChecksFirstAndDownloadRequiresSecondExplicitConfirmation()throws Exception{
  ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{
   app.repo.nextFetchElapsed=Long.MAX_VALUE;click(app,"Mehr");click(app,"App & Updates");c.resume();AtomicInteger opened=new AtomicInteger();String feed=new JSONObject().put("wearVersionCode",BuildConfig.VERSION_CODE+1).put("wearVersion","next").put("wearApkUrl","/apk/next.apk").put("wearApkBytes",4).put("wearApkSha256",String.join("",java.util.Collections.nCopies(64,"0"))).toString();
   app.updateConnectionFactory=url->{opened.incrementAndGet();return new Fake(url,url.getPath().equals("/update.json")?feed:"test");};app.checkUpdate();completeIo(app,"updateRequest");assertEquals(1,opened.get());AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing());dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,opened.get());
   app.checkUpdate();completeIo(app,"updateRequest");assertEquals(2,opened.get());dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();completeIo(app,"updateRequest");assertEquals(3,opened.get());assertEquals(0,app.repo.journeys.all().length());c.pause();
  }finally{c.stop().destroy();}
 }
}
